async function renderLedger7(){const m=$("acct7Ledger");if(!m)return;STATE.ledger=await get7("/api/accounting/ledger");const d=STATE.ledger,balanced=Math.abs(n7(d.summary.debit)-n7(d.summary.credit))<.01;m.innerHTML=`<div class="acct7-shell">${header7("LEDGER","สมุดบัญชีเบื้องต้น","เก็บยอดยกมา รายการปรับปรุง และรายการที่ระบบ v7 โพสต์ให้อัตโนมัติ เพื่อให้ฝ่ายบัญชีตรวจเดบิต/เครดิตต่อได้",'<button class="acct7-btn primary" id="acct7AddJournal">+ รายการปรับปรุง</button>')}<div class="acct7-kpis">${kpi7("เดบิตรวม",money7(d.summary.debit),"ยอดยกมา + สมุดรายวัน")}${kpi7("เครดิตรวม",money7(d.summary.credit),"ยอดยกมา + สมุดรายวัน")}${kpi7("สมดุล",balanced?"สมดุล":"ไม่สมดุล",balanced?"เดบิต = เครดิต":"ควรตรวจยอดยกมา",balanced?"good":"bad")}${kpi7("รายการสมุดรายวัน",String((d.journals||[]).length),"แสดงล่าสุดสูงสุด 1,000 บรรทัด")}</div><div class="acct7-grid2"><div class="acct7-card"><div class="acct7-card-head"><div><h4>งบทดลอง</h4><p>ยอดตามบัญชีจากข้อมูลที่โพสต์เข้า Ledger v7</p></div><button class="acct7-btn" id="acct7TbCsv">CSV</button></div><div class="acct7-table-wrap"><table class="acct7-table"><thead><tr><th>รหัส</th><th>บัญชี</th><th class="num">เดบิต</th><th class="num">เครดิต</th><th class="num">คงเหลือ</th></tr></thead><tbody>${(d.trialBalance||[]).map(r=>`<tr><td><span class="acct7-code">${esc7(r.accountCode)}</span></td><td>${esc7(r.accountName)}</td><td class="num">${money7(r.debit)}</td><td class="num">${money7(r.credit)}</td><td class="num"><b>${money7(r.balance)}</b></td></tr>`).join("")||'<tr><td colspan="5">'+empty7("ยังไม่มีรายการใน Ledger")+'</td></tr>'}</tbody></table></div></div><div class="acct7-card"><div class="acct7-card-head"><div><h4>ผังบัญชี</h4><p>บัญชีระบบเริ่มต้นสำหรับ SME</p></div></div><div class="acct7-list">${(d.coa||[]).map(r=>`<div class="acct7-row"><div><strong><span class="acct7-code">${esc7(r.code)}</span> ${esc7(r.name)}</strong><small>${esc7(r.type)}</small></div></div>`).join("")}</div></div></div><div class="acct7-card"><div class="acct7-card-head"><div><h4>สมุดรายวันล่าสุด</h4><p>ดูแหล่งที่มาของแต่ละบรรทัดเพื่อไล่ตรวจย้อนหลังได้</p></div></div><div class="acct7-table-wrap"><table class="acct7-table"><thead><tr><th>วันที่</th><th>อ้างอิง</th><th>บัญชี</th><th>ที่มา</th><th class="num">เดบิต</th><th class="num">เครดิต</th></tr></thead><tbody>${(d.journals||[]).slice(0,150).map(r=>`<tr><td>${d7(r.date)}</td><td>${esc7(r.reference||r.journalId)}</td><td>${esc7(r.accountCode)} · ${esc7(r.accountName)}</td><td>${esc7(r.sourceType||"manual")}</td><td class="num">${n7(r.debit)?money7(r.debit):"—"}</td><td class="num">${n7(r.credit)?money7(r.credit):"—"}</td></tr>`).join("")}</tbody></table></div></div></div>`;$("acct7AddJournal").onclick=()=>openJournal7(d.coa||[]);$("acct7TbCsv").onclick=()=>download7("trial-balance.csv",csv7(d.trialBalance||[]))}
function openJournal7(coa){const opts=coa.map(x=>`<option value="${attr7(x.code)}|${attr7(x.name)}">${esc7(x.code)} · ${esc7(x.name)}</option>`).join(""),body=modal7("รายการปรับปรุง","สำหรับนักบัญชี: เดบิต 1 บัญชี เครดิต 1 บัญชี จำนวนเท่ากัน",`<form class="acct7-form"><div class="acct7-field"><label>วันที่</label><input class="acct7-input" name="date" type="date" value="${today7()}"></div><div class="acct7-field"><label>อ้างอิง</label><input class="acct7-input" name="reference" placeholder="JV / เอกสารอ้างอิง"></div><div class="acct7-field full"><label>คำอธิบาย</label><input class="acct7-input" name="description" required></div><div class="acct7-field"><label>เดบิตบัญชี</label><select class="acct7-select" name="debitAccount">${opts}</select></div><div class="acct7-field"><label>เครดิตบัญชี</label><select class="acct7-select" name="creditAccount">${opts}</select></div><div class="acct7-field full"><label>จำนวนเงิน</label><input class="acct7-input" name="amount" type="number" step="0.01" min="0.01" required></div><div class="acct7-form-actions"><button class="acct7-btn" type="button" data-close>ยกเลิก</button><button class="acct7-btn primary" type="submit">โพสต์รายการ</button></div></form>`);body.querySelector("[data-close]").onclick=closeModal7;body.querySelector("form").onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,a=n7(formVal7(f,"amount")),[dc,dn]=formVal7(f,"debitAccount").split("|"),[cc,cn]=formVal7(f,"creditAccount").split("|");try{await post7("/api/accounting/journal",{date:formVal7(f,"date"),reference:formVal7(f,"reference"),description:formVal7(f,"description"),lines:[{accountCode:dc,accountName:dn,debit:a,credit:0},{accountCode:cc,accountName:cn,debit:0,credit:a}]});closeModal7();toast7("โพสต์สมุดรายวันแล้ว");await renderLedger7()}catch(err){toast7(err.message,true)}}}

