async function renderMigration7(){const m=$("acct7Migration");if(!m)return;STATE.migration=await get7("/api/accounting/migration");const d=STATE.migration;m.innerHTML=`<div class="acct7-shell">${header7("SWITCHING CENTER","ย้ายข้อมูลจากระบบเดิม","ไม่ต้องเริ่มใหม่ นำอดีตมาเก็บค้นหาได้ และย้ายยอดคงเหลือที่จำเป็นเพื่อใช้งานต่อจากวันปัจจุบัน",'<button class="acct7-btn" id="acct7OpeningManual">+ ยอดยกมา</button><button class="acct7-btn" id="acct7Backup">สำรองข้อมูลบริษัท</button>')}<div class="acct7-wizard-steps"><div class="acct7-step current"><b>1 · เลือกข้อมูล</b><small>คู่ค้า / เจ้าหนี้ / ยอดยกมา / ประวัติเดิม</small></div><div class="acct7-step"><b>2 · อัปโหลดไฟล์</b><small>CSV หรือ Excel</small></div><div class="acct7-step"><b>3 · จับคู่คอลัมน์</b><small>ระบบช่วยเดาให้ แก้ได้</small></div><div class="acct7-step"><b>4 · ตรวจผล</b><small>สำเร็จกี่รายการ ผิดตรงไหน</small></div></div><div class="acct7-grid2"><div class="acct7-card"><div class="acct7-card-head"><div><h4>นำเข้าข้อมูล</h4><p>แนะนำ: ประวัติ 3 ปี → “ประวัติเดิม”, รายการค้าง ณ วันย้าย → “เจ้าหนี้/ยอดยกมา”</p></div></div><div class="acct7-form"><div class="acct7-field"><label>ประเภทข้อมูล</label><select class="acct7-select" id="acct7MigType"><option value="archive">ประวัติรายรับ/รายจ่ายเดิม (Archive)</option><option value="contacts">ลูกค้าและผู้ขาย</option><option value="receivables">ลูกหนี้ค้างรับ</option><option value="payables">เจ้าหนี้ค้างจ่าย</option><option value="opening">ยอดยกมา</option></select></div><div class="acct7-field"><label>ชื่อระบบเดิม</label><input class="acct7-input" id="acct7MigSource" placeholder="เช่น PEAK, FlowAccount, Excel"></div><div class="acct7-field"><label>ไฟล์ตัวอย่าง</label><button class="acct7-btn" type="button" id="acct7MigTemplate">ดาวน์โหลด Template ตามประเภท</button></div><div class="acct7-field full"><div class="acct7-filebox"><input id="acct7MigFile" type="file" accept=".csv,.xlsx,.xls,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"><p style="margin:8px 0 0;font-size:10px;color:#8e8e93">ไฟล์จะถูกอ่านใน browser ก่อน แล้วส่งเฉพาะข้อมูลที่จับคู่แล้วเข้าระบบ</p></div></div><div class="acct7-field full" id="acct7MigMapping"></div></div></div><div class="acct7-card"><div class="acct7-card-head"><div><h4>สถานะการย้าย</h4><p>ข้อมูลเดิมยังอยู่ที่ระบบเดิมได้ ระบบนี้เพิ่มข้อมูลใหม่โดยไม่ลบต้นฉบับ</p></div></div><div class="acct7-kpis" style="grid-template-columns:repeat(2,minmax(0,1fr))">${kpi7("ประวัติเดิม",String(d.summary.archiveRows||0),"รายการ Archive")}${kpi7("คู่ค้า",String(d.summary.contactRows||0),"ลูกค้า/ผู้ขาย")}${kpi7("เจ้าหนี้ยกมา",String(d.summary.payableRows||0),"รายการคงค้าง")}${kpi7("ยอดยกมา",String(d.summary.openingRows||0),d.summary.openingBalanced?`เดบิต = เครดิต ${money7(d.summary.openingDebit)}`:`เดบิต ${money7(d.summary.openingDebit)} · เครดิต ${money7(d.summary.openingCredit)}`,d.summary.openingBalanced?"good":"bad")}</div><div class="acct7-list" style="margin-top:12px">${(d.imports||[]).slice(0,10).map(x=>`<div class="acct7-row"><div><strong>${esc7(x.fileName||x.type)}</strong><small>${d7(x.importedAt)} · ${esc7(x.type)} · ${x.success}/${x.total}</small></div><span class="acct7-status ${statusClass7(x.status)}">${esc7(x.status)}</span></div>`).join("")||empty7("ยังไม่มีประวัติการนำเข้า")}</div></div></div><div class="acct7-note"><span>🧭</span><span><strong>วิธีที่ปลอดภัยที่สุดสำหรับบริษัทที่ใช้ระบบเก่ามาหลายปี</strong> คือเก็บอดีตเป็น Archive ที่ค้นได้ แล้วนำเฉพาะคู่ค้า เจ้าหนี้/ลูกหนี้ค้าง และยอดยกมาของวัน Cut-over มาทำงานต่อ ไม่ต้องสร้างบัญชีย้อนหลังทุก transaction ใหม่</span></div></div>`;$("acct7MigFile").onchange=e=>prepareMigration7(e.target.files?.[0]);$("acct7MigType").onchange=()=>{if(MIG_FILE)prepareMigration7(MIG_FILE)};$("acct7MigTemplate").onclick=downloadMigrationTemplate7;$("acct7Backup").onclick=backup7;if($("acct7OpeningManual"))$("acct7OpeningManual").onclick=openOpening7}
async function parseMatrix7(file){const ext=file.name.split(".").pop().toLowerCase();if(ext==="csv"){const text=await file.text(),rows=[],re=/(,|\n|^)(?:"([^"]*(?:""[^"]*)*)"|([^",\n]*))/g;let row=[],last=0,m;while((m=re.exec(text))){const sep=m[1],val=(m[2]??m[3]??"").replace(/""/g,'"');if(sep==="\n"){rows.push(row);row=[]}row.push(val);last=re.lastIndex}if(row.length)rows.push(row);return rows.filter(r=>r.some(x=>String(x).trim()))}let XLSX=window.XLSX;if(!XLSX){if(typeof ensureXlsx==="function")XLSX=await ensureXlsx();else{await new Promise((ok,bad)=>{const s=document.createElement("script");s.src="https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js";s.onload=ok;s.onerror=bad;document.head.appendChild(s)});XLSX=window.XLSX}}const wb=XLSX.read(await file.arrayBuffer(),{type:"array",cellDates:true}),ws=wb.Sheets[wb.SheetNames[0]];return XLSX.utils.sheet_to_json(ws,{header:1,raw:false,defval:""})}
function normHead7(v){return String(v||"").toLowerCase().replace(/[\s_.\-\/()]/g,"")}
function guessField7(field,headers){const aliases={name:["ชื่อ","name","customername","vendorname","suppliername"],type:["ประเภท","type"],taxId:["taxid","เลขผู้เสียภาษี","taxno"],branch:["สาขา","branch"],email:["email","อีเมล"],phone:["phone","โทรศัพท์","tel"],address:["address","ที่อยู่"],paymentTerms:["เครดิตเทอม","paymentterms","creditterm"],defaultWhtRate:["wht","withholding"],issueDate:["วันที่เอกสาร","issuedate","date"],dueDate:["duedate","วันครบกำหนด"],supplier:["supplier","vendor","ผู้ขาย","เจ้าหนี้"],supplierTaxId:["suppliertaxid","vendortaxid","taxid"],customer:["customer","ลูกค้า","payer"],customerTaxId:["customertaxid","taxid","เลขผู้เสียภาษีลูกค้า"],invoiceNo:["invoiceno","invoice","เลขใบแจ้งหนี้"],billNo:["billno","invoice","เลขบิล","เลขใบแจ้งหนี้"],taxInvoiceNo:["taxinvoice","เลขใบกำกับ"],category:["category","หมวด"],description:["description","รายละเอียด","note"],grossAmount:["grossamount","amount","ยอด","total"],vatAmount:["vatamount","vat"],whtRate:["whtrate","wht%"],whtAmount:["whtamount","withholdingamount"],paidAmount:["paidamount","จ่ายแล้ว","receivedamount"],settledAmount:["settledamount","ยอดตัดแล้ว"],outstanding:["outstanding","คงค้าง","balance"],asOfDate:["asofdate","วันที่ยอดยกมา","date"],accountCode:["accountcode","รหัสบัญชี","code"],accountName:["accountname","ชื่อบัญชี"],debit:["debit","เดบิต"],credit:["credit","เครดิต"],reference:["reference","ref","อ้างอิง"],note:["note","หมายเหตุ"],transactionDate:["transactiondate","date","วันที่"],direction:["direction","type","รายรับรายจ่าย"],docNo:["docno","documentno","เลขเอกสาร","invoice"],party:["party","vendor","customer","คู่ค้า"],amount:["amount","ยอด","total"],vat:["vat"],wht:["wht"],status:["status","สถานะ"],sourceRef:["sourceref","ref","id"],attachmentUrl:["attachment","url","เอกสาร"]};const nh=headers.map(normHead7),names=aliases[field]||[field];let idx=nh.findIndex(h=>names.some(a=>h===normHead7(a)||h.includes(normHead7(a))));return idx>=0?idx:""}
function downloadMigrationTemplate7(){const type=$("acct7MigType")?.value||"archive",fields=MIG_FIELDS[type]||[];const labels=fields.map(f=>MIG_LABEL[f]||f),sample=Object.fromEntries(fields.map(f=>[f,""]));if(type==="contacts")Object.assign(sample,{type:"ลูกค้า",name:"บริษัท ตัวอย่าง จำกัด",taxId:"0100000000000",branch:"สำนักงานใหญ่",paymentTerms:30});if(type==="receivables")Object.assign(sample,{issueDate:today7(),dueDate:today7(),customer:"บริษัท ลูกค้า จำกัด",invoiceNo:"INV-001",grossAmount:10700,vatAmount:700,outstanding:10700});if(type==="payables")Object.assign(sample,{issueDate:today7(),dueDate:today7(),supplier:"บริษัท ผู้ขาย จำกัด",billNo:"BILL-001",grossAmount:5350,vatAmount:350,outstanding:5350});if(type==="opening")Object.assign(sample,{asOfDate:today7(),accountCode:"1000",accountName:"เงินสดและธนาคาร",debit:100000,credit:0,reference:"Cut-over"});if(type==="archive")Object.assign(sample,{transactionDate:today7(),direction:"รายจ่าย",docNo:"OLD-001",party:"คู่ค้าตัวอย่าง",description:"ประวัติจากระบบเดิม",amount:1000,status:"ประวัติ"});const row=fields.map(f=>sample[f]??"");download7(`migration-template-${type}.csv`,"\ufeff"+labels.map(v=>`"${String(v).replace(/"/g,'""')}"`).join(",")+"\r\n"+row.map(v=>`"${String(v).replace(/"/g,'""')}"`).join(","))}
function openOpening7(){const body=modal7("เพิ่มยอดยกมา","ใช้สำหรับ Cut-over จากระบบเดิม กรอกเดบิตหรือเครดิตเพียงด้านเดียวต่อบรรทัด",`<form class="acct7-form"><div class="acct7-field"><label>วันที่ยอดยกมา</label><input class="acct7-input" type="date" name="asOfDate" value="${today7()}" required></div><div class="acct7-field"><label>รหัสบัญชี</label><input class="acct7-input" name="accountCode" placeholder="เช่น 1000" required></div><div class="acct7-field full"><label>ชื่อบัญชี</label><input class="acct7-input" name="accountName" placeholder="เช่น เงินสดและธนาคาร" required></div><div class="acct7-field"><label>เดบิต</label><input class="acct7-input" type="number" step="0.01" min="0" name="debit" value="0"></div><div class="acct7-field"><label>เครดิต</label><input class="acct7-input" type="number" step="0.01" min="0" name="credit" value="0"></div><div class="acct7-field"><label>อ้างอิง</label><input class="acct7-input" name="reference" placeholder="ยอดจากระบบเดิม"></div><div class="acct7-field"><label>หมายเหตุ</label><input class="acct7-input" name="note"></div><div class="acct7-form-actions full"><button class="acct7-btn" type="button" data-close>ยกเลิก</button><button class="acct7-btn primary" type="submit">บันทึกยอดยกมา</button></div></form>`);body.querySelector("[data-close]").onclick=closeModal7;body.querySelector("form").onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));if(n7(data.debit)>0&&n7(data.credit)>0)return toast7("หนึ่งบรรทัดให้กรอกเดบิตหรือเครดิตเพียงด้านเดียว",true);if(!(n7(data.debit)>0||n7(data.credit)>0))return toast7("กรอกยอดเดบิตหรือเครดิต",true);try{await post7("/api/accounting/opening",data);closeModal7();toast7("บันทึกยอดยกมาแล้ว");await renderMigration7()}catch(err){toast7(err.message,true)}}}
async function prepareMigration7(file){if(!file)return;MIG_FILE=file;try{MIG_MATRIX=await parseMatrix7(file);if(!MIG_MATRIX.length)throw new Error("ไฟล์ไม่มีข้อมูล");const headers=MIG_MATRIX[0].map(String),type=$("acct7MigType").value,fields=MIG_FIELDS[type];MIG_MAP={};fields.forEach(f=>MIG_MAP[f]=guessField7(f,headers));const mount=$("acct7MigMapping");mount.innerHTML=`<div class="acct7-card" style="padding:13px"><div class="acct7-card-head"><div><h4>จับคู่คอลัมน์ · ${esc7(file.name)}</h4><p>พบ ${Math.max(0,MIG_MATRIX.length-1)} แถว ระบบเดา mapping ให้แล้ว ตรวจอีกครั้งก่อนนำเข้า</p></div></div><div class="acct7-map-grid">${fields.map(f=>`<div class="acct7-map-row"><label>${esc7(MIG_LABEL[f]||f)}</label><select class="acct7-select" data-map-field="${attr7(f)}"><option value="">— ไม่ใช้ —</option>${headers.map((h,i)=>`<option value="${i}" ${String(MIG_MAP[f])===String(i)?"selected":""}>${esc7(h||`คอลัมน์ ${i+1}`)}</option>`).join("")}</select></div>`).join("")}</div><div class="acct7-migration-preview" style="margin-top:10px"><div class="acct7-table-wrap"><table class="acct7-table"><thead><tr>${headers.slice(0,8).map(h=>`<th>${esc7(h)}</th>`).join("")}</tr></thead><tbody>${MIG_MATRIX.slice(1,6).map(r=>`<tr>${headers.slice(0,8).map((_,i)=>`<td>${esc7(r[i]??"")}</td>`).join("")}</tr>`).join("")}</tbody></table></div></div><div class="acct7-actions" style="margin-top:12px"><button class="acct7-btn primary" id="acct7MigImport">นำเข้า ${Math.max(0,MIG_MATRIX.length-1)} รายการ</button></div></div>`;mount.querySelectorAll("[data-map-field]").forEach(s=>s.onchange=()=>MIG_MAP[s.dataset.mapField]=s.value===""?"":Number(s.value));$("acct7MigImport").onclick=runMigration7}catch(e){toast7(e.message,true)}}
async function runMigration7(){if(!MIG_MATRIX)return;const type=$("acct7MigType").value,headers=MIG_MATRIX[0],fields=MIG_FIELDS[type],rows=MIG_MATRIX.slice(1).filter(r=>r.some(x=>String(x||"").trim())).map(r=>{const o={};fields.forEach(f=>{const i=MIG_MAP[f];if(i!==""&&i!=null)o[f]=r[i]??""});return o});if(rows.length>10000)return toast7("หนึ่งครั้งนำเข้าได้สูงสุด 10,000 รายการ",true);if(!confirm(`นำเข้า ${rows.length} รายการจาก ${MIG_FILE.name}?\nข้อมูลเดิมในระบบจะไม่ถูกลบ`))return;try{const out=await post7("/api/accounting/migration",{type,fileName:MIG_FILE.name,sourceSystem:$("acct7MigSource").value,rows});toast7(`นำเข้าสำเร็จ ${out.success}/${out.total}`);if(out.failed)alert(`นำเข้าสำเร็จ ${out.success} รายการ\nต้องแก้ ${out.failed} รายการ\n\n`+(out.errors||[]).slice(0,20).map(x=>`แถว ${x.row}: ${x.error}`).join("\n"));MIG_FILE=null;MIG_MATRIX=null;await renderMigration7()}catch(e){toast7(e.message,true)}}
async function backup7(){try{toast7("กำลังเตรียมไฟล์สำรอง…");const d=await get7("/api/accounting/backup");download7(`accounting-backup-${today7()}.json`,JSON.stringify(d,null,2),"application/json;charset=utf-8");toast7("ดาวน์โหลดไฟล์สำรองแล้ว")}catch(e){toast7(e.message,true)}}

/* AUDIT / ACCESS */
async function renderAudit7(){const m=$("acct7Audit");if(!m)return;const [audit,who]=await Promise.all([get7("/api/accounting/audit",{limit:300}),get7("/api/accounting/whoami")]);STATE.audit=audit;STATE.who=who;let access={rows:[]};if(who.role==="owner")access=await get7("/api/accounting/access").catch(()=>({rows:[]}));STATE.access=access;m.innerHTML=`<div class="acct7-shell">${header7("CONTROL & TRUST","Audit และสิทธิ์ผู้ใช้งาน","รู้ว่าใครแก้อะไรเมื่อไร และแยกสิทธิ์เจ้าของ/บัญชี/ผู้อนุมัติ/ดูอย่างเดียว โดยไม่ใช้ลิงก์ Owner ร่วมกัน",who.role==="owner"?'<button class="acct7-btn primary" id="acct7NewAccess">+ สร้างลิงก์ผู้ใช้</button>':'')}<div class="acct7-kpis">${kpi7("สิทธิ์ของคุณ",who.roleLabel||who.role,who.name||"")}${kpi7("Audit ล่าสุด",String((audit.rows||[]).length),"แสดงสูงสุด 300 รายการ")}${kpi7("ลิงก์ผู้ใช้",String((access.rows||[]).length),who.role==="owner"?"Owner จัดการได้":"ดูโดย Owner")}${kpi7("ข้อมูลย้อนกลับ",(audit.rows||[]).some(x=>x.beforeJson)?"มี":"กำลังสะสม","Before / After","good")}</div>${who.role==="owner"?`<div class="acct7-card"><div class="acct7-card-head"><div><h4>ลิงก์สิทธิ์เฉพาะคน</h4><p>อย่าส่งลิงก์ Owner ให้ทีม สร้างลิงก์ตามบทบาทแทน และยกเลิกได้ทันที</p></div></div><div class="acct7-list">${(access.rows||[]).map(r=>`<div class="acct7-row"><div><strong>${esc7(r.name)}</strong><small>${esc7(r.role)} · สร้าง ${d7(r.createdAt)}</small></div><div class="acct7-actions"><button class="acct7-btn" data-copy-access="${attr7(r.url)}">คัดลอกลิงก์</button><button class="acct7-btn danger" data-revoke-access="${attr7(r.token)}">ยกเลิก</button></div></div>`).join("")||empty7("ยังไม่มีลิงก์ทีม แนะนำให้สร้างให้ฝ่ายบัญชี/ผู้อนุมัติแยกจาก Owner")}</div></div>`:""}<div class="acct7-card"><div class="acct7-card-head"><div><h4>ประวัติการเปลี่ยนแปลง</h4><p>ค้นจากคนทำ รายการ หรือประเภทข้อมูล</p></div><input class="acct7-input" id="acct7AuditQ" placeholder="ค้น Audit…" style="max-width:280px"></div><div id="acct7AuditTable"></div></div></div>`;if($("acct7NewAccess"))$("acct7NewAccess").onclick=openAccess7;m.querySelectorAll("[data-copy-access]").forEach(b=>b.onclick=()=>navigator.clipboard.writeText(b.dataset.copyAccess).then(()=>toast7("คัดลอกลิงก์แล้ว")));m.querySelectorAll("[data-revoke-access]").forEach(b=>b.onclick=async()=>{if(!confirm("ยกเลิกลิงก์นี้ทันที?"))return;await post7("/api/accounting/access-revoke",{token:b.dataset.revokeAccess});toast7("ยกเลิกลิงก์แล้ว");renderAudit7()});$("acct7AuditQ").oninput=drawAudit7;drawAudit7()}
function drawAudit7(){const m=$("acct7AuditTable"),q=($("acct7AuditQ")?.value||"").toLowerCase(),rows=(STATE.audit?.rows||[]).filter(r=>!q||[r.actor,r.action,r.entityType,r.entityId,r.summary].join(" ").toLowerCase().includes(q));m.innerHTML=rows.length?`<div class="acct7-table-wrap"><table class="acct7-table"><thead><tr><th>เวลา</th><th>ผู้ดำเนินการ</th><th>การกระทำ</th><th>รายการ</th><th>สรุป</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${d7(r.time)}<div class="muted">${new Date(r.time).toLocaleTimeString("th-TH",{hour:"2-digit",minute:"2-digit"})}</div></td><td>${esc7(r.actor||"System")}</td><td><span class="acct7-status">${esc7(r.action)}</span></td><td>${esc7(r.entityType)}<div class="muted">${esc7(r.entityId)}</div></td><td>${esc7(r.summary||"—")}</td></tr>`).join("")}</tbody></table></div>`:empty7("ยังไม่มี Audit Log ที่ตรงกับการค้นหา")}
function openAccess7(){const body=modal7("สร้างลิงก์ผู้ใช้งาน","แต่ละคนใช้ลิงก์ของตัวเอง ยกเลิกสิทธิ์ได้โดยไม่กระทบ Owner",`<form class="acct7-form"><div class="acct7-field"><label>ชื่อผู้ใช้</label><input class="acct7-input" name="name" required placeholder="เช่น น้องแอน ฝ่ายบัญชี"></div><div class="acct7-field"><label>สิทธิ์</label><select class="acct7-select" name="role"><option value="accountant">บัญชี — ทำงานบัญชีได้</option><option value="approver">ผู้อนุมัติ — ตรวจ/อนุมัติเบิกจ่าย</option><option value="viewer">ดูอย่างเดียว — แก้ไขไม่ได้</option></select></div><div class="acct7-field full"><label>LINE User ID (ถ้ามี)</label><input class="acct7-input" name="lineUserId"></div><div class="acct7-form-actions"><button class="acct7-btn" type="button" data-close>ยกเลิก</button><button class="acct7-btn primary" type="submit">สร้างลิงก์</button></div></form>`);body.querySelector("[data-close]").onclick=closeModal7;body.querySelector("form").onsubmit=async e=>{e.preventDefault();try{const out=await post7("/api/accounting/access",Object.fromEntries(new FormData(e.currentTarget)));closeModal7();await navigator.clipboard.writeText(out.record.url).catch(()=>{});alert(`สร้างลิงก์แล้ว\n\n${out.record.url}\n\nระบบพยายามคัดลอกไว้ให้แล้ว`);await renderAudit7()}catch(err){toast7(err.message,true)}}}

window.AccountingSuiteRefresh=async p=>{const map={search:renderSearch7,payables:renderPayables7,contacts:renderContacts7,"period-close":()=>renderPeriod7($("acct7PeriodMonth")?.value||month7()),"tax-center":()=>renderTax7($("acct7TaxMonth")?.value||month7()),ledger:renderLedger7,migration:renderMigration7,audit:renderAudit7};if(map[p])return map[p]()};
